import json, subprocess
def lines(args):
    return subprocess.run(args, text=True, capture_output=True, check=True).stdout.splitlines()
data = {
    "containers": [x for x in lines(["docker", "ps", "-a", "--filter", "label=com.docker.compose.project", "--format", "{{.Labels}}"]) if "com.docker.compose.project=pixelgym-it-" in x],
    "volumes": [x for x in lines(["docker", "volume", "ls", "--format", "{{.Name}}"]) if x.startswith("pixelgym-it-")],
    "networks": [x for x in lines(["docker", "network", "ls", "--format", "{{.Name}}"]) if x.startswith("pixelgym-it-")],
    "images": [x for x in lines(["docker", "image", "ls", "--format", "{{.Repository}}:{{.Tag}}"]) if x.startswith("pixelgym-it-")],
}
print(json.dumps(data, sort_keys=True))
